// ── Text-to-JSON parser for datum-cli agents ───────────────────────────────
// datum-cli agents return text (no schema). CLI commands output JSON directly.
// Parse it out, stripping markdown fences and prose the agent might add.

function parseAgentJson(text, fallback) {
  if (!text || typeof text !== 'string') return fallback || null
  const cleaned = text.replace(/```[a-z]*\n?/g, '').trim()
  // Find the first { or [ and last } or ]
  const start = cleaned.search(/[{[]/)
  const end = Math.max(cleaned.lastIndexOf('}'), cleaned.lastIndexOf(']'))
  if (start === -1 || end === -1) return fallback || null
  try { return JSON.parse(cleaned.slice(start, end + 1)) }
  catch { return fallback || null }
}

