      "id": "task-001",
      "title": "WaveResult.to_dict / from_dict — round-trip serialization",
      "files": ["datum/wave_builder.py", "tests/test_wave_builder.py"],
      "acceptance_criteria": [
        "AC1: WaveResult has a to_dict() method returning a plain dict with keys 'waves' (list of lists of str) and 'stats' (dict with total_tasks, num_waves, max_parallelism, critical_path_length as ints)",
        "AC2: WaveResult has a classmethod from_dict(d) that reconstructs a WaveResult from a dict produced by to_dict()",
        "AC3: Round-trip: WaveResult.from_dict(wr.to_dict()).waves == wr.waves and stats match for any valid WaveResult"
      ],
      "red_note": "Write tests that call .to_dict() and .from_dict() on WaveResult instances. These will fail because the methods do not exist yet. APPEND tests to the existing file.",
      "stage": "behavioral",
      "depends_on": []
    },
    "task-002": {
