Kahn's algorithm:
```js
function buildWaves(lanePlan) {
  const lanes = lanePlan.lanes
  const ids = Object.keys(lanes)
  const inDeg = {}
  const adj = {}
  for (const id of ids) {
    const deps = lanes[id].depends_on || []
    inDeg[id] = deps.length
    for (const dep of deps) {
      ;(adj[dep] = adj[dep] || []).push(id)
    }
  }
  const waves = []
  let queue = ids.filter(id => inDeg[id] === 0).sort()
  while (queue.length > 0) {
    waves.push([...queue])
    const next = []
    for (const id of queue) {
      for (const child of adj[id] || []) {
        inDeg[child]--
        if (inDeg[child] === 0) next.push(child)
      }
    }
    queue = next.sort()
  }
  return waves
}
```

Standard Kahn's: if there's a cycle, the cyclic nodes never reach in-degree 0, so they're silently dropped from the output. `waves.flat().length < ids.length` means tasks disappeared.

