let selectedPath = null;

async function fetchJson(url) {
  const r = await fetch(url);
  return r.ok ? r.json() : null;
}

function esc(s) { const d = document.createElement('div'); d.textContent = s; return d.innerHTML; }

function timeAgo(ts) {
  const s = Math.floor((Date.now()/1000) - ts);
  if (s < 60) return `${s}s ago`;
  if (s < 3600) return `${Math.floor(s/60)}m ago`;
  if (s < 86400) return `${Math.floor(s/3600)}h ago`;
  return `${Math.floor(s/86400)}d ago`;
}

function fmtDuration(ms) {
  if (!ms) return '—';
  const s = Math.round(ms / 1000);
  if (s < 60) return `${s}s`;
  return `${Math.floor(s/60)}m ${s%60}s`;
}

function fmtTokens(n) {
  if (!n) return '—';
  if (n > 1000000) return `${(n/1000000).toFixed(1)}M`;
  if (n > 1000) return `${Math.round(n/1000)}K`;
  return String(n);
}

function statusBadge(status) {
  const cls = status === 'running' ? 'running' : status === 'completed' ? 'completed' : status === 'failed' ? 'failed' : 'done';
  return `<span class="badge badge--${cls}">${status}</span>`;
}

function agentStateBadge(state) {
  if (state === 'running') return '<span class="spinner"></span>';
  if (state === 'queued') return '<span class="badge badge--queued">queued</span>';
  return '';
}

async function renderSidebar() {
  const data = await fetchJson('/api/runs');
  if (!data || !data.length) {
    document.getElementById('sidebar').innerHTML = '<div class="empty">No workflows found</div>';
    return;
  }
  document.getElementById('sidebar').innerHTML = data.map(r => `
    <div class="run-card" data-path="${esc(r.path)}" onclick="selectRun(this)" ${selectedPath === r.path ? 'data-selected' : ''}>
      <div class="run-name">${esc(r.name)} ${statusBadge(r.status)}</div>
