@layer layout {
  body { font-family: var(--font-sans); background: var(--bg); color: var(--text); line-height: 1.5; }
  .shell { max-width: 1400px; margin: 0 auto; padding: 1.5rem; display: grid; grid-template-columns: 320px 1fr; gap: 1.5rem; min-height: 100dvh; }
  @media (max-width: 900px) { .shell { grid-template-columns: 1fr; } }

  header { grid-column: 1 / -1; display: flex; align-items: baseline; gap: 1rem; flex-wrap: wrap; }
  header h1 { font-family: var(--font-mono); font-size: 1.1rem; font-weight: 600; color: var(--text-bright); letter-spacing: -0.02em; }
  .meta { font-size: 0.75rem; color: var(--text-dim); font-family: var(--font-mono); }
}

@layer components {
  .sidebar { display: flex; flex-direction: column; gap: 0.5rem; overflow-y: auto; max-height: calc(100dvh - 5rem); }

  .run-card {
    background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius);
    padding: 0.75rem 1rem; cursor: pointer; transition: border-color 0.15s var(--ease);
  }
  .run-card:hover, .run-card[data-selected] { border-color: var(--accent); background: var(--bg-hover); }

  .run-name { font-family: var(--font-mono); font-size: 0.85rem; color: var(--text-bright); font-weight: 500; }
  .run-id { font-size: 0.65rem; color: var(--text-dim); font-family: var(--font-mono); margin-top: 2px; }
  .run-meta { display: flex; gap: 0.75rem; margin-top: 0.4rem; font-size: 0.7rem; font-family: var(--font-mono); color: var(--text-dim); }

  .detail { overflow-y: auto; max-height: calc(100dvh - 5rem); }

  .summary-bar {
    display: flex; gap: 1.5rem; padding: 0.75rem 1rem; background: var(--bg-card);
    border: 1px solid var(--border); border-radius: var(--radius); font-family: var(--font-mono);
    font-size: 0.8rem; margin-bottom: 1rem; flex-wrap: wrap;
  }
  .summary-bar dt { color: var(--text-dim); font-size: 0.6rem; text-transform: uppercase; letter-spacing: 0.08em; }
  .summary-bar dd { color: var(--text-bright); font-weight: 600; font-size: 1rem; }

  .phase-group { margin-bottom: 1rem; }
  .phase-header {
    display: flex; align-items: center; gap: 0.5rem; padding: 0.5rem 0.75rem;
    background: var(--bg-phase); border-radius: var(--radius-sm); margin-bottom: 0.4rem;
    font-family: var(--font-mono); font-size: 0.8rem; font-weight: 600; color: var(--accent);
  }
  .phase-header .dot { width: 8px; height: 8px; border-radius: 50%; }

  .agent-row {
    display: grid; grid-template-columns: 2fr 80px 70px 60px 3fr;
    gap: 0.5rem; align-items: center; padding: 0.5rem 0.75rem;
    border-left: 3px solid transparent; margin-left: 0.5rem;
    font-size: 0.75rem; font-family: var(--font-mono);
    transition: border-color 0.15s var(--ease);
  }
  .agent-row:hover { border-left-color: var(--accent); }
  .agent-row[data-state="running"] { border-left-color: var(--green); }
  .agent-row[data-state="queued"] { border-left-color: var(--yellow); }
  .agent-row[data-state="done"] { border-left-color: var(--border); }

  .agent-label { color: var(--text-bright); font-weight: 500; }
  .agent-model { color: var(--text-dim); font-size: 0.65rem; }
  .agent-tokens { color: var(--text-dim); text-align: right; font-size: 0.7rem; }
  .agent-duration { color: var(--text-dim); text-align: right; font-size: 0.7rem; }
  .agent-activity { color: var(--text-dim); font-size: 0.68rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

  .badge {
    display: inline-flex; align-items: center; gap: 0.2rem; padding: 0.1rem 0.4rem;
    border-radius: 100px; font-size: 0.6rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.04em;
  }
  .badge--running { background: color-mix(in srgb, var(--green) 15%, transparent); color: var(--green); }
  .badge--queued { background: color-mix(in srgb, var(--yellow) 15%, transparent); color: var(--yellow); }
  .badge--done { background: color-mix(in srgb, var(--text-dim) 10%, transparent); color: var(--text-dim); }
  .badge--completed { background: color-mix(in srgb, var(--green) 15%, transparent); color: var(--green); }
  .badge--failed { background: color-mix(in srgb, var(--red) 15%, transparent); color: var(--red); }

  .logs {
    margin-top: 1rem; padding: 0.75rem; background: var(--bg-card); border: 1px solid var(--border);
    border-radius: var(--radius); font-family: var(--font-mono); font-size: 0.7rem; color: var(--text-dim);
    max-height: 200px; overflow-y: auto;
  }
  .logs div { padding: 0.15rem 0; border-bottom: 1px solid color-mix(in srgb, var(--border) 30%, transparent); }
  .logs div:last-child { border-bottom: none; }

  .empty { text-align: center; padding: 3rem; color: var(--text-dim); font-family: var(--font-mono); font-size: 0.85rem; }

  @keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.4; } }
  @keyframes spin { to { transform: rotate(360deg); } }
  .spinner { display: inline-block; width: 8px; height: 8px; border: 2px solid var(--green); border-top-color: transparent; border-radius: 50%; animation: spin 0.8s linear infinite; }
}

@layer states {
  [data-status="running"] .phase-header .dot { background: var(--green); animation: pulse 1.5s infinite; }
  [data-status="completed"] .phase-header .dot { background: var(--green); }
  [data-status="failed"] .phase-header .dot { background: var(--red); }
}
</style>
</head>
<body>
<div class="shell">
  <header>
    <h1>datum workflows</h1>
    <span class="meta" id="clock"></span>
  </header>
  <div class="sidebar" id="sidebar"></div>
  <div class="detail" id="detail"><div class="empty">Select a workflow run</div></div>
</div>

<script>
let selectedPath = null;

async function fetchJson(url) {
  const r = await fetch(url);
  return r.ok ? r.json() : null;
}

function esc(s) { const d = document.createElement('div'); d.textContent = s; return d.innerHTML; }

function timeAgo(ts) {
  const s = Math.floor((Date.now()/1000) - ts);
  if (s < 60) return `${s}s ago`;
  if (s < 3600) return `${Math.floor(s/60)}m ago`;
  if (s < 86400) return `${Math.floor(s/3600)}h ago`;
  return `${Math.floor(s/86400)}d ago`;
}

function fmtDuration(ms) {
  if (!ms) return '—';
  const s = Math.round(ms / 1000);
  if (s < 60) return `${s}s`;
  return `${Math.floor(s/60)}m ${s%60}s`;
}

function fmtTokens(n) {
  if (!n) return '—';
  if (n > 1000000) return `${(n/1000000).toFixed(1)}M`;
  if (n > 1000) return `${Math.round(n/1000)}K`;
  return String(n);
}

function statusBadge(status) {
  const cls = status === 'running' ? 'running' : status === 'completed' ? 'completed' : status === 'failed' ? 'failed' : 'done';
  return `<span class="badge badge--${cls}">${status}</span>`;
}

function agentStateBadge(state) {
  if (state === 'running') return '<span class="spinner"></span>';
  if (state === 'queued') return '<span class="badge badge--queued">queued</span>';
  return '';
}

async function renderSidebar() {
  const data = await fetchJson('/api/runs');
  if (!data || !data.length) {
    document.getElementById('sidebar').innerHTML = '<div class="empty">No workflows found</div>';
    return;
  }
  document.getElementById('sidebar').innerHTML = data.map(r => `
    <div class="run-card" data-path="${esc(r.path)}" onclick="selectRun(this)" ${selectedPath === r.path ? 'data-selected' : ''}>
      <div class="run-name">${esc(r.name)} ${statusBadge(r.status)}</div>
      <div class="run-id">${esc(r.id)} · ${esc(r.project.slice(0,25))}</div>
      <div class="run-meta">
        <span>${r.done}/${r.total_agents} agents</span>
        <span>${esc(r.phase)}</span>
        <span>${timeAgo(r.mtime)}</span>
      </div>
    </div>
  `).join('');

  if (selectedPath) loadDetail(selectedPath);
  else if (data.length) selectRun(document.querySelector('.run-card'));
}

function selectRun(el) {
  document.querySelectorAll('.run-card').forEach(c => c.removeAttribute('data-selected'));
  el.setAttribute('data-selected', '');
  selectedPath = el.dataset.path;
  loadDetail(selectedPath);
}

async function loadDetail(path) {
  const d = await fetchJson(`/api/detail?path=${encodeURIComponent(path)}`);
  if (!d || d.error) { document.getElementById('detail').innerHTML = '<div class="empty">Cannot load</div>'; return; }

  const pct = d.total_agents ? Math.round((d.phases.reduce((s,p) => s + p.agents.filter(a => a.state === 'done').length, 0)) / d.total_agents * 100) : 0;

  let html = `
    <div class="summary-bar" data-status="${d.status}">
      <dl><dt>Status</dt><dd>${statusBadge(d.status)}</dd></dl>
      <dl><dt>Agents</dt><dd>${d.total_agents}</dd></dl>
      <dl><dt>Tokens</dt><dd>${fmtTokens(d.total_tokens)}</dd></dl>
      <dl><dt>Tools</dt><dd>${d.total_tool_calls}</dd></dl>
      <dl><dt>Duration</dt><dd>${fmtDuration(d.duration_ms)}</dd></dl>
      <dl><dt>Model</dt><dd>${esc((d.model||'').replace('claude-',''))}</dd></dl>
      <dl><dt>Progress</dt><dd>${pct}%</dd></dl>
    </div>
  `;

  for (const ph of d.phases) {
    const phDone = ph.agents.filter(a => a.state === 'done').length;
    const phActive = ph.agents.filter(a => a.state === 'running').length;
    const phState = phActive > 0 ? 'running' : phDone === ph.agents.length && ph.agents.length > 0 ? 'completed' : 'pending';

    html += `<div class="phase-group" data-status="${phState}">`;
    html += `<div class="phase-header"><span class="dot"></span> ${esc(ph.title)} <span class="meta">${phDone}/${ph.agents.length}</span></div>`;

    for (const a of ph.agents) {
      const activity = a.state === 'running'
        ? (a.last_tool ? `${a.last_tool}: ${a.last_summary}` : 'working...')
        : a.state === 'done'
          ? (a.result_preview ? a.result_preview.slice(0, 80) : 'done')
          : a.prompt_preview.slice(0, 80);

      html += `
        <div class="agent-row" data-state="${a.state}">
          <div class="agent-label">${agentStateBadge(a.state)} ${esc(a.label)}${a.attempt > 1 ? ` <span class="meta">×${a.attempt}</span>` : ''}</div>
          <div class="agent-model">${esc(a.model)}</div>
          <div class="agent-tokens">${fmtTokens(a.tokens)}</div>
          <div class="agent-duration">${a.duration_s ? a.duration_s + 's' : '—'}</div>
          <div class="agent-activity" title="${esc(activity)}">${esc(activity)}</div>
        </div>
      `;
    }
    html += `</div>`;
  }

  if (d.logs && d.logs.length) {
    html += `<div class="logs">${d.logs.map(l => `<div>${esc(l)}</div>`).join('')}</div>`;
  }

  document.getElementById('detail').innerHTML = html;
}

function tick() { document.getElementById('clock').textContent = new Date().toLocaleTimeString(); }
setInterval(tick, 1000);
setInterval(renderSidebar, 2000);
tick();
renderSidebar();
</script>
</body>
</html>"""


class DashboardHandler(SimpleHTTPRequestHandler):
    def do_GET(self):
        parsed = urlparse(self.path)
        if parsed.path in ("/", "/index.html"):
            self._send_html(DASHBOARD_HTML)
        elif parsed.path == "/api/runs":
            self._send_json(find_workflow_runs())
        elif parsed.path == "/api/detail":
            qs = parse_qs(parsed.query)
            path = qs.get("path", [""])[0]
            if path:
                self._send_json(get_workflow_detail(path))
            else:
                self._send_json({"error": "missing path"})
        else:
            self.send_error(404)

    def _send_json(self, data):
        body = json.dumps(data).encode()
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", len(body))
        self.send_header("Access-Control-Allow-Origin", "*")
        self.end_headers()
        self.wfile.write(body)

    def _send_html(self, html):
        body = html.encode()
        self.send_response(200)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", len(body))
        self.end_headers()
        self.wfile.write(body)

    def log_message(self, fmt, *a):
        pass


if __name__ == "__main__":
    import sys

    port = int(sys.argv[1]) if len(sys.argv) > 1 else PORT
    server = HTTPServer(("0.0.0.0", port), DashboardHandler)
    print(f"datum workflow dashboard → http://0.0.0.0:{port}")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nshutdown")

