  .badge {
    display: inline-flex; align-items: center; gap: 0.2rem; padding: 0.1rem 0.4rem;
    border-radius: 100px; font-size: 0.6rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.04em;
  }
  .badge--running { background: color-mix(in srgb, var(--green) 15%, transparent); color: var(--green); }
  .badge--queued { background: color-mix(in srgb, var(--yellow) 15%, transparent); color: var(--yellow); }
  .badge--done { background: color-mix(in srgb, var(--text-dim) 10%, transparent); color: var(--text-dim); }
  .badge--completed { background: color-mix(in srgb, var(--green) 15%, transparent); color: var(--green); }
  .badge--failed { background: color-mix(in srgb, var(--red) 15%, transparent); color: var(--red); }

  .logs {
    margin-top: 1rem; padding: 0.75rem; background: var(--bg-card); border: 1px solid var(--border);
    border-radius: var(--radius); font-family: var(--font-mono); font-size: 0.7rem; color: var(--text-dim);
    max-height: 200px; overflow-y: auto;
  }
  .logs div { padding: 0.15rem 0; border-bottom: 1px solid color-mix(in srgb, var(--border) 30%, transparent); }
  .logs div:last-child { border-bottom: none; }
  .empty { text-align: center; padding: 3rem; color: var(--text-dim); font-family: var(--font-mono); font-size: 0.85rem; }

  @keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.4; } }
  @keyframes spin { to { transform: rotate(360deg); } }
  @keyframes slideDown { from { opacity: 0; max-height: 0; } to { opacity: 1; max-height: 500px; } }
  .spinner { display: inline-block; width: 8px; height: 8px; border: 2px solid var(--green); border-top-color: transparent; border-radius: 50%; animation: spin 0.8s linear infinite; }
}
@layer states {
  [data-status="running"] .phase-header .dot { background: var(--green); animation: pulse 1.5s infinite; }
  [data-status="completed"] .phase-header .dot { background: var(--green); }
  [data-status="failed"] .phase-header .dot { background: var(--red); }
}
</style>
</head>
<body>
<div class="shell">
  <header>
    <h1>datum workflows</h1>
    <span class="meta" id="clock"></span>
  </header>
  <div class="sidebar">
    <div class="filters" id="filters"></div>
    <div id="runs"></div>
  </div>
  <div class="detail" id="detail"><div class="empty">Select a workflow run</div></div>
</div>

<script>
let selectedPath = null;
let activeFilter = 'all';
let allRuns = [];

async function fetchJson(url) { const r = await fetch(url); return r.ok ? r.json() : null; }
function esc(s) { const d = document.createElement('div'); d.textContent = s; return d.innerHTML; }
function timeAgo(ts) {
  const s = Math.floor((Date.now()/1000) - ts);
  if (s < 60) return `${s}s ago`; if (s < 3600) return `${Math.floor(s/60)}m ago`;
  if (s < 86400) return `${Math.floor(s/3600)}h ago`; return `${Math.floor(s/86400)}d ago`;
}
function fmtDuration(ms) { if (!ms) return '—'; const s = Math.round(ms/1000); return s < 60 ? `${s}s` : `${Math.floor(s/60)}m ${s%60}s`; }
function fmtTokens(n) { if (!n) return '—'; if (n > 1e6) return `${(n/1e6).toFixed(1)}M`; if (n > 1e3) return `${Math.round(n/1e3)}K`; return String(n); }
function statusBadge(st) { const c = st === 'running' ? 'running' : st === 'completed' ? 'completed' : st === 'failed' ? 'failed' : 'done'; return `<span class="badge badge--${c}">${st}</span>`; }

function setFilter(f) {
  activeFilter = f;
  document.querySelectorAll('.filter-btn').forEach(b => { b.toggleAttribute('data-active', b.dataset.filter === f); });
  document.querySelectorAll('.run-card').forEach(c => {
    const show = f === 'all' || c.dataset.status === f;
    c.hidden = !show;
  });
}

function toggleAgent(id) {
  const el = document.getElementById('ad-' + id);
  if (!el) return;
  el.toggleAttribute('data-open');
}

async function renderSidebar() {
  allRuns = await fetchJson('/api/runs') || [];
  if (!allRuns.length) { document.getElementById('runs').innerHTML = '<div class="empty">No workflows found</div>'; return; }

  const counts = { all: allRuns.length, running: 0, completed: 0, failed: 0 };
  allRuns.forEach(r => { if (counts[r.status] !== undefined) counts[r.status]++; });

  document.getElementById('filters').innerHTML = ['all','running','failed','completed'].map(f =>
    `<button class="filter-btn" data-filter="${f}" ${activeFilter === f ? 'data-active' : ''} onclick="setFilter('${f}')">${f} <span class="count">${counts[f]}</span></button>`
  ).join('');

  document.getElementById('runs').innerHTML = allRuns.map(r => `
    <div class="run-card" data-path="${esc(r.path)}" data-status="${r.status}" onclick="selectRun(this)" ${selectedPath === r.path ? 'data-selected' : ''} ${activeFilter !== 'all' && r.status !== activeFilter ? 'hidden' : ''}>
      <div class="run-name">${esc(r.name)} ${statusBadge(r.status)}</div>
      <div class="run-id">${esc(r.id)} · ${esc(r.project.slice(0,25))}</div>
      <div class="run-meta">
        <span>${r.done}/${r.total_agents} agents</span>
        <span>${fmtTokens(r.tokens)} tok</span>
        <span>${timeAgo(r.mtime)}</span>
      </div>
    </div>
  `).join('');

  if (selectedPath) loadDetail(selectedPath);
  else if (allRuns.length) { const first = document.querySelector('.run-card:not([hidden])'); if (first) selectRun(first); }
}

function selectRun(el) {
  document.querySelectorAll('.run-card').forEach(c => c.removeAttribute('data-selected'));
  el.setAttribute('data-selected', '');
  selectedPath = el.dataset.path;
  loadDetail(selectedPath);
}

async function loadDetail(path) {
  const d = await fetchJson(`/api/detail?path=${encodeURIComponent(path)}`);
  if (!d || d.error) { document.getElementById('detail').innerHTML = '<div class="empty">Cannot load</div>'; return; }

  const allAgents = d.phases.flatMap(p => p.agents);
  const pct = allAgents.length ? Math.round(allAgents.filter(a => a.state === 'done').length / allAgents.length * 100) : 0;

  let html = `
    <div class="summary-bar" data-status="${d.status}">
      <dl><dt>Status</dt><dd>${statusBadge(d.status)}</dd></dl>
      <dl><dt>Agents</dt><dd>${d.total_agents}</dd></dl>
      <dl><dt>Tokens</dt><dd>${fmtTokens(d.total_tokens)}</dd></dl>
      <dl><dt>Tools</dt><dd>${d.total_tool_calls}</dd></dl>
      <dl><dt>Duration</dt><dd>${fmtDuration(d.duration_ms)}</dd></dl>
      <dl><dt>Model</dt><dd>${esc((d.model||'').replace('claude-',''))}</dd></dl>
      <dl><dt>Progress</dt><dd>${pct}%</dd></dl>
    </div>
  `;

  let agentIdx = 0;
  for (const ph of d.phases) {
    const phDone = ph.agents.filter(a => a.state === 'done').length;
    const phActive = ph.agents.filter(a => a.state === 'running').length;
    const phState = phActive > 0 ? 'running' : phDone === ph.agents.length && ph.agents.length > 0 ? 'completed' : 'pending';

    html += `<div class="phase-group" data-status="${phState}">`;
    html += `<div class="phase-header"><span class="dot"></span> ${esc(ph.title)} <span class="meta">${phDone}/${ph.agents.length}</span></div>`;

    for (const a of ph.agents) {
      const aid = agentIdx++;
      const activity = a.state === 'running'
        ? (a.last_tool ? `${a.last_tool}: ${a.last_summary}` : 'working...')
        : a.state === 'done'
          ? (a.result_preview ? a.result_preview.slice(0, 80) : 'done')
          : a.prompt_preview.slice(0, 80);

      html += `
        <div class="agent-row" data-state="${a.state}" onclick="toggleAgent(${aid})">
          <div class="agent-label">${a.state === 'running' ? '<span class="spinner"></span> ' : ''}${esc(a.label)}${a.attempt > 1 ? ` <span class="meta">×${a.attempt}</span>` : ''}</div>
          <div class="agent-model">${esc(a.model)}</div>
          <div class="agent-tokens">${fmtTokens(a.tokens)}</div>
          <div class="agent-duration">${a.duration_s ? a.duration_s + 's' : '—'}</div>
          <div class="agent-activity" title="${esc(activity)}">${esc(activity)}</div>
        </div>
        <div class="agent-detail" id="ad-${aid}">
          <div class="kv">
            <span>Model: <strong>${esc(a.model)}</strong></span>
            <span>Tokens: <strong>${fmtTokens(a.tokens)}</strong></span>
            <span>Tools: <strong>${a.tool_calls}</strong></span>
            <span>Duration: <strong>${a.duration_s}s</strong></span>
            <span>Attempt: <strong>${a.attempt}</strong></span>
            ${a.last_tool ? `<span>Last tool: <strong>${esc(a.last_tool)}</strong></span>` : ''}
          </div>
          ${a.prompt_preview ? `<div class="section"><div class="section-title">Prompt</div><div class="section-body">${esc(a.prompt_preview)}</div></div>` : ''}
          ${a.last_summary ? `<div class="section"><div class="section-title">Last Activity</div><div class="section-body">${esc(a.last_summary)}</div></div>` : ''}
          ${a.result_preview ? `<div class="section"><div class="section-title">Result</div><div class="section-body">${esc(a.result_preview)}</div></div>` : ''}
        </div>
      `;
    }
    html += `</div>`;
  }

  if (d.logs && d.logs.length) {
    html += `<div class="logs">${d.logs.map(l => `<div>${esc(l)}</div>`).join('')}</div>`;
  }

  document.getElementById('detail').innerHTML = html;
}

function tick() { document.getElementById('clock').textContent = new Date().toLocaleTimeString(); }

