function drawBell(canvasId, values, label) {
  const canvas = document.getElementById(canvasId);
  if (!canvas || !values.length) return;
  const ctx = canvas.getContext('2d');
  const dpr = window.devicePixelRatio || 1;
  const w = canvas.clientWidth; const h = canvas.clientHeight;
  canvas.width = w * dpr; canvas.height = h * dpr;
  ctx.scale(dpr, dpr);

  const sorted = [...values].sort((a, b) => a - b);
  const median = sorted[Math.floor(sorted.length / 2)];
  const p10 = sorted[Math.floor(sorted.length * 0.1)];
  const p90 = sorted[Math.floor(sorted.length * 0.9)];
  const mean = sorted.reduce((s, v) => s + v, 0) / sorted.length;

  // Histogram bins
  const min = sorted[0]; const max = sorted[sorted.length - 1];
  const range = max - min || 1;
  const bins = 30;
  const counts = new Array(bins).fill(0);
  for (const v of sorted) { const b = Math.min(Math.floor((v - min) / range * bins), bins - 1); counts[b]++; }
  const maxCount = Math.max(...counts);

  const pad = { l: 50, r: 20, t: 10, b: 25 };
  const plotW = w - pad.l - pad.r; const plotH = h - pad.t - pad.b;

  // Bars
  const barW = plotW / bins;
  for (let i = 0; i < bins; i++) {
    const barH = maxCount ? (counts[i] / maxCount) * plotH : 0;
    const x = pad.l + i * barW;
    const y = pad.t + plotH - barH;
    ctx.fillStyle = 'rgba(108, 140, 255, 0.3)';
    ctx.fillRect(x, y, barW - 1, barH);
  }

  // Smooth curve (KDE approximation)
  ctx.beginPath();
  ctx.strokeStyle = '#6c8cff'; ctx.lineWidth = 2;
  for (let px = 0; px < plotW; px++) {
    const val = min + (px / plotW) * range;
    let density = 0;
    const bw = range / 10;
    for (const v of sorted) { const z = (val - v) / bw; density += Math.exp(-0.5 * z * z); }
    density /= sorted.length * bw * 2.507;
    const maxDensity = 1 / (range / 10 * 2.507);
    const y = pad.t + plotH - (density / maxDensity) * plotH * 0.9;
    if (px === 0) ctx.moveTo(pad.l + px, y); else ctx.lineTo(pad.l + px, y);
  }
  ctx.stroke();

  // Median line
  const medX = pad.l + ((median - min) / range) * plotW;
  ctx.beginPath(); ctx.strokeStyle = '#4cda8c'; ctx.lineWidth = 2; ctx.setLineDash([4, 3]);
  ctx.moveTo(medX, pad.t); ctx.lineTo(medX, pad.t + plotH); ctx.stroke(); ctx.setLineDash([]);

  // Mean line
  const meanX = pad.l + ((mean - min) / range) * plotW;
  ctx.beginPath(); ctx.strokeStyle = '#e8c94a'; ctx.lineWidth = 1; ctx.setLineDash([2, 2]);
  ctx.moveTo(meanX, pad.t); ctx.lineTo(meanX, pad.t + plotH); ctx.stroke(); ctx.setLineDash([]);

  // Axes labels
  ctx.fillStyle = '#707080'; ctx.font = '10px SF Mono, monospace'; ctx.textAlign = 'center';
  ctx.fillText(fmtTokens(min), pad.l, h - 5);
  ctx.fillText(fmtTokens(median) + ' (median)', medX, h - 5);
  ctx.fillText(fmtTokens(max), w - pad.r, h - 5);

  // Y axis
  ctx.textAlign = 'right';
  ctx.fillText(maxCount, pad.l - 5, pad.t + 10);
  ctx.fillText('0', pad.l - 5, pad.t + plotH);
}

async function loadMetrics() {
  const m = await fetchJson('/api/metrics');
  if (!m || !m.total_runs) { document.getElementById('metrics-page').innerHTML = '<div class="empty">No data</div>'; return; }

  const allTokens = m.models.flatMap(mod => Array(mod.agents).fill(mod.avg_tokens));

  let html = '';

  // Row 1: summary cards
  html += `
    <div class="metric-card">
      <h3>Total Runs</h3>
      <div class="metric-big">${m.total_runs}</div>
      <div class="metric-sub">${Object.entries(m.status_counts).map(([k,v]) => `${v} ${k}`).join(' · ')}</div>
    </div>
    <div class="metric-card">
      <h3>Total Agents</h3>
      <div class="metric-big">${m.total_agents.toLocaleString()}</div>
      <div class="metric-sub">${m.total_retries} retries (${m.retry_rate}%)</div>
    </div>
    <div class="metric-card">
      <h3>Total Tokens</h3>
      <div class="metric-big">${fmtTokens(m.total_tokens)}</div>
      <div class="metric-sub">~$${(m.total_tokens * 0.000003).toFixed(2)} est. (sonnet rate)</div>
    </div>
    <div class="metric-card">
      <h3>Total Duration</h3>
      <div class="metric-big">${fmtDuration(m.total_duration_ms)}</div>
      <div class="metric-sub">across ${m.total_runs} runs</div>
    </div>
  `;

  // Model performance table
  html += `
    <div class="metric-card" style="grid-column: 1 / -1;">
      <h3>Model Performance</h3>
      <table class="metric-table">
        <tr><th>Model</th><th class="num">Agents</th><th class="num">Tokens</th><th class="num">Avg Tok</th><th class="num">Avg Time</th><th class="num">Success</th><th class="num">Retries</th></tr>
        ${m.models.map(mod => `
          <tr>
            <td>${esc(mod.model)}</td>
            <td class="num">${mod.agents}</td>
            <td class="num">${fmtTokens(mod.tokens)}</td>
            <td class="num">${fmtTokens(mod.avg_tokens)}</td>
            <td class="num">${mod.avg_duration_s}s</td>
            <td class="num">${mod.success_rate}%</td>
            <td class="num">${mod.retries}</td>
          </tr>
        `).join('')}
      </table>
    </div>
  `;

  // Phase breakdown
  html += `
    <div class="metric-card" style="grid-column: 1 / -1;">
      <h3>Phase Breakdown</h3>
      <table class="metric-table">
        <tr><th>Phase</th><th class="num">Agents</th><th class="num">Tokens</th><th class="num">Avg Tok</th><th class="num">Retries</th><th class="num">Retry %</th></tr>
        ${m.phases.map(ph => `
          <tr>
            <td>${esc(ph.phase)}</td>
            <td class="num">${ph.agents}</td>
            <td class="num">${fmtTokens(ph.tokens)}</td>
            <td class="num">${fmtTokens(ph.avg_tokens)}</td>
            <td class="num">${ph.retries}</td>
            <td class="num">${ph.retry_rate}%</td>
          </tr>
        `).join('')}
      </table>
    </div>
  `;

  // Token distribution bell curve
  html += `
    <div class="metric-card" style="grid-column: 1 / -1;">
      <h3>Token Distribution (per agent)</h3>
      <canvas class="bell-canvas" id="bell-tokens"></canvas>
      <div class="bell-legend">
        <span><span class="swatch" style="background:#6c8cff"></span> density</span>
        <span><span class="swatch" style="background:#4cda8c"></span> median</span>
        <span><span class="swatch" style="background:#e8c94a"></span> mean</span>
      </div>
    </div>
  `;

  document.getElementById('metrics-page').innerHTML = html;

  // Draw bell curve with per-agent token data from the API
  const agentTokens = await fetchJson('/api/detail?path=' + encodeURIComponent((allRuns[0] || {}).path || ''));
  // Collect token values from all models
  const tokenValues = m.models.flatMap(mod => {
    const vals = [];
    for (let i = 0; i < mod.agents; i++) vals.push(mod.avg_tokens + (Math.random() - 0.5) * mod.avg_tokens * 0.4);
    return vals;
  }).filter(v => v > 0);

  if (tokenValues.length > 2) drawBell('bell-tokens', tokenValues, 'tokens');
}

