| `.phase-group` | `<div class="mb-4">` |
| `.phase-header` | `<div class="flex items-center gap-2 px-3 py-2 bg-bg-phase rounded-sm mb-1.5 font-mono text-[0.8rem] font-semibold text-accent">` |
