| `.tab-btn` | `<button class="font-mono text-[0.75rem] px-3 py-1 rounded-sm border border-border bg-transparent text-dim cursor-pointer transition-all duration-150 font-semibold hover:border-accent hover:text-[#e0e0e8]">` |
