| `.metric-table` | `<table class="w-full border-collapse font-mono text-[0.72rem]">` |
| `.metric-table th` | `<th class="text-left text-dim text-[0.6rem] uppercase tracking-wide px-2 py-1.5 border-b border-border font-semibold">` |
| `.metric-table td` | `<td class="px-2 py-1.5 border-b border-border/40 text-[#e0e0e8]">` |
| `.metric-table td:first-child` | Use `first:text-bright first:font-medium` on the `<td>` or apply manually to the first `<td>` in each row |
| `.metric-table .num` | `text-right tabular-nums` |

#### 3.13 Bell Canvas & Legend (Replaced by Chart.js)

These CSS classes are **deleted entirely** -- they are replaced by Chart.js DOM:
- `.bell-canvas`
- `.bell-legend`
- `.bell-legend .swatch`

#### 3.14 Empty State

| Original CSS | Tailwind Replacement |
|---|---|
| `.empty` | `<div class="text-center p-12 text-dim font-mono text-[0.85rem]">` |

### 4. Replacing drawBell() with Chart.js

The current `drawBell()` function (lines 615-686, 72 lines) does:
1. Creates histogram with 30 bins
2. Draws KDE density curve
3. Draws dashed median line (green)
4. Draws dashed mean line (yellow)
5. Labels: min, median, max on x-axis; count on y-axis

Replace with a Chart.js bar chart + line overlay + annotation plugin lines.

#### 4.1 New function: `renderTokenChart(canvasId, values)`

```js
let tokenChart = null;

function renderTokenChart(canvasId, values) {
  const canvas = document.getElementById(canvasId);
  if (!canvas || !values.length) return;

  // Destroy previous instance
  if (tokenChart) { tokenChart.destroy(); tokenChart = null; }

  const sorted = [...values].sort((a, b) => a - b);
  const median = sorted[Math.floor(sorted.length / 2)];
  const mean = sorted.reduce((s, v) => s + v, 0) / sorted.length;
  const min = sorted[0];
  const max = sorted[sorted.length - 1];
  const range = max - min || 1;

  // Build histogram bins
  const binCount = 30;
  const binWidth = range / binCount;
  const bins = new Array(binCount).fill(0);
  const labels = [];
  for (let i = 0; i < binCount; i++) {
    const lo = min + i * binWidth;
    labels.push(fmtTokens(Math.round(lo)));
    for (const v of sorted) {
      const b = Math.min(Math.floor((v - min) / range * binCount), binCount - 1);
      if (b === i) bins[i]++;
    }
  }
  // Fix: rebuild bins properly (the loop above double-counts)
  // Actually, rebuild cleanly:
  const counts = new Array(binCount).fill(0);
  for (const v of sorted) {
    const b = Math.min(Math.floor((v - min) / range * binCount), binCount - 1);
    counts[b]++;
  }

  // KDE density curve (same algorithm as original)
  const bw = range / 10;
  const kdePoints = [];
  for (let i = 0; i < binCount; i++) {
    const val = min + (i + 0.5) * binWidth;
    let density = 0;
    for (const v of sorted) {
      const z = (val - v) / bw;
      density += Math.exp(-0.5 * z * z);
    }
    density /= sorted.length * bw * 2.507;
    kdePoints.push(density);
  }
  // Normalize KDE to match histogram scale
  const maxCount = Math.max(...counts);
  const maxDensity = Math.max(...kdePoints);
  const kdeScaled = kdePoints.map(d => maxDensity > 0 ? (d / maxDensity) * maxCount : 0);

  tokenChart = new Chart(canvas, {
    type: 'bar',
    data: {
      labels: labels,
      datasets: [
        {
          label: 'Count',
          data: counts,
          backgroundColor: 'rgba(108, 140, 255, 0.3)',
          borderColor: 'rgba(108, 140, 255, 0.5)',
          borderWidth: 1,
          barPercentage: 1.0,
          categoryPercentage: 1.0,
          order: 2,
        },
        {
          label: 'Density',
          data: kdeScaled,
          type: 'line',
          borderColor: '#6c8cff',
          borderWidth: 2,
          pointRadius: 0,
          fill: false,
          tension: 0.4,
          order: 1,
        },
      ],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      scales: {
        x: {
          grid: { display: false },
          ticks: {
            color: '#707080',
            font: { family: "'SF Mono', monospace", size: 10 },
            maxTicksLimit: 6,
          },
          border: { color: '#2a2a3a' },
        },
        y: {
          grid: { color: 'rgba(42, 42, 58, 0.3)' },
          ticks: {
            color: '#707080',
            font: { family: "'SF Mono', monospace", size: 10 },
          },
          border: { color: '#2a2a3a' },
        },
      },
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: '#12121a',
          borderColor: '#2a2a3a',
          borderWidth: 1,
          titleFont: { family: "'SF Mono', monospace" },
          bodyFont: { family: "'SF Mono', monospace" },
        },
        annotation: {
          annotations: {
            medianLine: {
              type: 'line',
              xMin: ((median - min) / binWidth),
              xMax: ((median - min) / binWidth),
              borderColor: '#4cda8c',
              borderWidth: 2,
              borderDash: [4, 3],
              label: {
                display: true,
                content: `Median: ${fmtTokens(median)}`,
                position: 'start',
                backgroundColor: 'rgba(76, 218, 140, 0.15)',
                color: '#4cda8c',
                font: { family: "'SF Mono', monospace", size: 10 },
              },
            },
            meanLine: {
              type: 'line',
              xMin: ((mean - min) / binWidth),
              xMax: ((mean - min) / binWidth),
              borderColor: '#e8c94a',
              borderWidth: 1,
              borderDash: [2, 2],
              label: {
                display: true,
                content: `Mean: ${fmtTokens(Math.round(mean))}`,
                position: 'end',
                backgroundColor: 'rgba(232, 201, 74, 0.15)',
                color: '#e8c94a',
                font: { family: "'SF Mono', monospace", size: 10 },
              },
            },
          },
        },
      },
    },
  });
}
```

