@layer reset, tokens, layout, components, states;
@layer reset { *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; } body { min-height: 100dvh; } }
@layer tokens {
  :root {
    --bg: #0a0a0f; --bg-card: #12121a; --bg-hover: #1a1a28; --bg-phase: #0e0e16;
    --bg-expand: #161622; --border: #2a2a3a; --text: #e0e0e8; --text-dim: #707080;
    --text-bright: #f0f0ff; --accent: #6c8cff; --green: #4cda8c; --yellow: #e8c94a;
    --red: #e84a5a; --orange: #e89a4a; --purple: #a06cff;
    --font-mono: 'SF Mono', 'Cascadia Code', 'JetBrains Mono', monospace;
    --font-sans: 'Inter', -apple-system, system-ui, sans-serif;
    --radius: 8px; --radius-sm: 4px; --ease: cubic-bezier(0.4, 0, 0.2, 1);
  }
}
@layer layout {
  body { font-family: var(--font-sans); background: var(--bg); color: var(--text); line-height: 1.5; }
  .shell { max-width: 1400px; margin: 0 auto; padding: 1.5rem; display: grid; grid-template-columns: 320px 1fr; gap: 1.5rem; min-height: 100dvh; }
  @media (max-width: 900px) { .shell { grid-template-columns: 1fr; } }
  header { grid-column: 1 / -1; display: flex; align-items: baseline; gap: 1rem; flex-wrap: wrap; }
  header h1 { font-family: var(--font-mono); font-size: 1.1rem; font-weight: 600; color: var(--text-bright); }
  .meta { font-size: 0.75rem; color: var(--text-dim); font-family: var(--font-mono); }
}
@layer components {
  .sidebar { display: flex; flex-direction: column; gap: 0.5rem; overflow-y: auto; max-height: calc(100dvh - 5rem); }
  .filters { display: flex; gap: 0.25rem; margin-bottom: 0.5rem; flex-wrap: wrap; }
  .filter-btn {
    font-family: var(--font-mono); font-size: 0.65rem; padding: 0.25rem 0.6rem;
    border-radius: 100px; border: 1px solid var(--border); background: transparent;
    color: var(--text-dim); cursor: pointer; transition: all 0.15s var(--ease);
    text-transform: uppercase; letter-spacing: 0.04em; font-weight: 600;
  }
  .filter-btn:hover { border-color: var(--accent); color: var(--text); }
  .filter-btn[data-active] { border-color: var(--accent); background: color-mix(in srgb, var(--accent) 15%, transparent); color: var(--accent); }
  .filter-btn .count { opacity: 0.6; margin-left: 0.2rem; }

  .run-card {
    background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius);
    padding: 0.75rem 1rem; cursor: pointer; transition: border-color 0.15s var(--ease);
  }
  .run-card:hover, .run-card[data-selected] { border-color: var(--accent); background: var(--bg-hover); }
  .run-card[hidden] { display: none; }
  .run-name { font-family: var(--font-mono); font-size: 0.85rem; color: var(--text-bright); font-weight: 500; }
  .run-id { font-size: 0.65rem; color: var(--text-dim); font-family: var(--font-mono); margin-top: 2px; }
  .run-meta { display: flex; gap: 0.75rem; margin-top: 0.4rem; font-size: 0.7rem; font-family: var(--font-mono); color: var(--text-dim); }

  .detail { overflow-y: auto; max-height: calc(100dvh - 5rem); }
  .summary-bar {
    display: flex; gap: 1.5rem; padding: 0.75rem 1rem; background: var(--bg-card);
    border: 1px solid var(--border); border-radius: var(--radius); font-family: var(--font-mono);
    font-size: 0.8rem; margin-bottom: 1rem; flex-wrap: wrap;
  }
  .summary-bar dt { color: var(--text-dim); font-size: 0.6rem; text-transform: uppercase; letter-spacing: 0.08em; }
  .summary-bar dd { color: var(--text-bright); font-weight: 600; font-size: 1rem; }

  .phase-group { margin-bottom: 1rem; }
  .phase-header {
    display: flex; align-items: center; gap: 0.5rem; padding: 0.5rem 0.75rem;
    background: var(--bg-phase); border-radius: var(--radius-sm); margin-bottom: 0.4rem;
    font-family: var(--font-mono); font-size: 0.8rem; font-weight: 600; color: var(--accent);
  }
  .phase-header .dot { width: 8px; height: 8px; border-radius: 50%; }

  .agent-row {
    display: grid; grid-template-columns: 2fr 80px 70px 60px 3fr;
    gap: 0.5rem; align-items: center; padding: 0.5rem 0.75rem;
    border-left: 3px solid transparent; margin-left: 0.5rem;
    font-size: 0.75rem; font-family: var(--font-mono);
    transition: border-color 0.15s var(--ease); cursor: pointer;
  }
  .agent-row:hover { border-left-color: var(--accent); background: var(--bg-hover); }
