  .agent-tokens { color: var(--text-dim); text-align: right; font-size: 0.7rem; }
  .agent-duration { color: var(--text-dim); text-align: right; font-size: 0.7rem; }
  .agent-activity { color: var(--text-dim); font-size: 0.68rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

  .agent-expand {
