function renderTokenChart(canvasId,values){
  const canvas=document.getElementById(canvasId);
  if(!canvas||!values.length)return;
  if(tokenChart){tokenChart.destroy();tokenChart=null}

  const sorted=[...values].sort((a,b)=>a-b);
  const median=sorted[Math.floor(sorted.length/2)];
  const mean=sorted.reduce((s,v)=>s+v,0)/sorted.length;
  const min=sorted[0],max=sorted[sorted.length-1],range=max-min||1;
  const bins=30,bw=range/bins;
  const counts=new Array(bins).fill(0);
  const labels=[];
  for(let i=0;i<bins;i++)labels.push(tok(Math.round(min+i*bw)));
  for(const v of sorted){const b=Math.min(Math.floor((v-min)/range*bins),bins-1);counts[b]++}

  const kdeBw=range/10,kde=[];
  for(let i=0;i<bins;i++){
    const val=min+(i+0.5)*bw;let d=0;
    for(const v of sorted){const z=(val-v)/kdeBw;d+=Math.exp(-0.5*z*z)}
    kde.push(d/(sorted.length*kdeBw*2.507));
  }
  const mx=Math.max(...counts),md=Math.max(...kde);
  const kdeScaled=kde.map(d=>md>0?(d/md)*mx:0);

  tokenChart=new Chart(canvas,{
    type:'bar',
    data:{labels,datasets:[
      {label:'Count',data:counts,backgroundColor:'rgba(108,140,255,0.3)',borderColor:'rgba(108,140,255,0.5)',borderWidth:1,barPercentage:1,categoryPercentage:1,order:2},
      {label:'Density',data:kdeScaled,type:'line',borderColor:'#6c8cff',borderWidth:2,pointRadius:0,fill:false,tension:0.4,order:1},
    ]},
    options:{
      responsive:true,maintainAspectRatio:false,
      scales:{
        x:{grid:{display:false},ticks:{color:'#707080',font:{family:"'SF Mono',monospace",size:10},maxTicksLimit:6},border:{color:'#2a2a3a'}},
        y:{grid:{color:'rgba(42,42,58,0.3)'},ticks:{color:'#707080',font:{family:"'SF Mono',monospace",size:10}},border:{color:'#2a2a3a'}},
      },
      plugins:{
        legend:{display:false},
        tooltip:{backgroundColor:'#12121a',borderColor:'#2a2a3a',borderWidth:1,titleFont:{family:"'SF Mono',monospace"},bodyFont:{family:"'SF Mono',monospace"}},
        annotation:{annotations:{
          med:{type:'line',xMin:(median-min)/bw,xMax:(median-min)/bw,borderColor:'#4cda8c',borderWidth:2,borderDash:[4,3],
            label:{display:true,content:'Median: '+tok(median),position:'start',backgroundColor:'rgba(76,218,140,0.15)',color:'#4cda8c',font:{family:"'SF Mono',monospace",size:10}}},
          avg:{type:'line',xMin:(mean-min)/bw,xMax:(mean-min)/bw,borderColor:'#e8c94a',borderWidth:1,borderDash:[2,2],
            label:{display:true,content:'Mean: '+tok(Math.round(mean)),position:'end',backgroundColor:'rgba(232,201,74,0.15)',color:'#e8c94a',font:{family:"'SF Mono',monospace",size:10}}},
        }},
      },
    },
  });
}

